#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#define ZYZTOOLS_CHANNEL "dropdown-harness"
#include <windows.h>
#include <cassert>
#include <iostream>
#include "../src/TrainingPilotDropdown.h"
#pragma comment(lib,"user32.lib")
#pragma comment(lib,"gdi32.lib")
void CheckDark(HWND popup){
 HDC dc=CreateCompatibleDC(nullptr);BITMAPINFO bitmap{};bitmap.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bitmap.bmiHeader.biWidth=144;bitmap.bmiHeader.biHeight=-20;bitmap.bmiHeader.biPlanes=1;bitmap.bmiHeader.biBitCount=32;bitmap.bmiHeader.biCompression=BI_RGB;void*bits=nullptr;HBITMAP image=CreateDIBSection(dc,&bitmap,DIB_RGB_COLORS,&bits,nullptr,0);auto old=SelectObject(dc,image);
 DRAWITEMSTRUCT item{};item.CtlID=1;item.itemID=7;item.hDC=dc;item.rcItem={0,0,144,20};SendMessage(popup,WM_DRAWITEM,0,reinterpret_cast<LPARAM>(&item));assert(GetPixel(dc,140,18)==RGB(45,45,45));item.itemState=ODS_SELECTED;SendMessage(popup,WM_DRAWITEM,0,reinterpret_cast<LPARAM>(&item));assert(GetPixel(dc,140,18)==RGB(72,72,72));SelectObject(dc,old);DeleteObject(image);DeleteDC(dc);
}
void Pump(){MSG msg{};while(PeekMessage(&msg,nullptr,0,0,PM_REMOVE)){TranslateMessage(&msg);DispatchMessage(&msg);}}
int main(){HWND owner=CreateWindowExA(0,"STATIC","Synthetic test owner",WS_POPUP,0,0,200,100,nullptr,nullptr,GetModuleHandle(nullptr),nullptr);assert(owner);std::string chosen;{TrainingPilotDropdown dropdown;std::vector<std::string> values;for(int i=1;i<=60;i++)values.push_back(std::string(i<10?"0":"")+std::to_string(i*10));assert(dropdown.Open(values,"080",[&](std::string value){chosen=value;},owner,false));assert(!IsWindowVisible(dropdown.Handle()));HWND combo=GetDlgItem(dropdown.Handle(),1);assert(combo);assert(GetWindowLongPtr(combo,GWL_STYLE)&CBS_OWNERDRAWFIXED);CheckDark(dropdown.Handle());assert(SendMessage(combo,CB_GETCOUNT,0,0)==60);assert((GetWindowLongPtr(combo,GWL_STYLE)&CBS_DROPDOWNLIST)==CBS_DROPDOWNLIST);COMBOBOXINFO info{sizeof(COMBOBOXINFO)};assert(GetComboBoxInfo(combo,&info));assert(info.hwndList);RECT dropped{};SendMessage(combo,CB_GETDROPPEDCONTROLRECT,0,reinterpret_cast<LPARAM>(&dropped));assert(dropped.bottom-dropped.top<=180);SendMessage(combo,CB_SETTOPINDEX,30,0);assert(SendMessage(combo,CB_GETTOPINDEX,0,0)==30);SendMessage(info.hwndList,WM_MOUSEMOVE,0,MAKELPARAM(10,500));SendMessage(info.hwndList,WM_TIMER,1,0);assert(SendMessage(combo,CB_GETTOPINDEX,0,0)==30);SendMessage(info.hwndList,WM_MOUSEWHEEL,MAKEWPARAM(0,120),0);assert(SendMessage(combo,CB_GETTOPINDEX,0,0)==27);SendMessage(info.hwndList,WM_MOUSEWHEEL,MAKEWPARAM(0,static_cast<WORD>(-240)),0);assert(SendMessage(combo,CB_GETTOPINDEX,0,0)==33);SendMessage(combo,CB_SETCURSEL,37,0);SendMessage(dropdown.Handle(),WM_COMMAND,MAKEWPARAM(1,CBN_SELENDOK),reinterpret_cast<LPARAM>(combo));assert(chosen.empty());assert(IsWindow(combo));Pump();assert(chosen=="380");assert(!dropdown.Handle());for(int i=0;i<20;i++){chosen.clear();assert(dropdown.Open(values,"080",[&](std::string value){chosen=value;},owner,false));combo=GetDlgItem(dropdown.Handle(),1);assert(GetComboBoxInfo(combo,&info));SendMessage(info.hwndList,WM_MOUSEMOVE,MK_LBUTTON,MAKELPARAM(10,500));SendMessage(info.hwndList,WM_LBUTTONUP,0,MAKELPARAM(10,500));assert(IsWindow(combo));Pump();assert(chosen.empty());assert(!dropdown.Handle());}}DestroyWindow(owner);std::cout<<"PASS: hidden dark-gray dropdown, bounded viewport, all 60 three-digit altitude choices, wheel scrolling, deferred selection, and 20 drag-off cancellations. No user windows or network touched.\n";}
